"use client";

import { useEffect, useState } from "react";
import { motion, useScroll, useTransform } from "framer-motion";
import { ArrowDown } from "@phosphor-icons/react";
import { onIntroRevealed } from "@/lib/introSignal";
import HeroTitle from "@/components/home/HeroTitle";

const container = {
  hidden: { opacity: 1 },
  show: {
    opacity: 1,
    transition: {
      // Stagger més ràpid perquè la frase es completi a ~0.9s (era ~1.75s)
      staggerChildren: 0.08,
      delayChildren: 0.05,
    },
  },
};

export default function Hero({
  embedded = false,
  introPending = false,
}: {
  embedded?: boolean;
  /** True quan l'IntroLoader es reproduirà: l'entrada espera el seu reveal. */
  introPending?: boolean;
}) {
  const { scrollY } = useScroll();
  const opacity = useTransform(scrollY, [0, 300], [1, 0]);
  const scale = useTransform(scrollY, [0, 300], [1, 0.95]);

  // Entrada sincronitzada amb el reveal de l'intro. Sense intro (sessió
  // repetida, altres contextos), entra directament des del SSR com sempre.
  const [entered, setEntered] = useState(!introPending);
  useEffect(() => {
    if (entered) return;
    return onIntroRevealed(() => setEntered(true));
  }, [entered]);

  // `embedded`: el hero s'incrusta com a overlay transparent dins l'escena
  // sticky (HeroScene a ShowcaseVideo) — sense fons ni alçada pròpia, omple el
  // contenidor. Si no, és la secció autònoma de 100dvh amb fons.
  const rootClass = embedded
    ? "absolute inset-0 flex flex-col w-full z-10 overflow-hidden"
    : "h-[100dvh] flex flex-col w-full relative z-10 overflow-hidden bg-surface-base";

  return (
    <section className={rootClass}>
      <motion.div
        variants={container}
        initial="hidden"
        animate="show"
        style={{ opacity, scale }}
        className="flex-1 flex flex-col justify-center items-start px-4 md:px-8 lg:px-24 relative"
      >
        {/* Lockup interactiu (efecte de cursor — veure HeroTitle.tsx).
            L'entrada subtil es fa per CSS: `hero-enter` quan pot arrencar, i
            `hero-enter-wait` mentre l'intro cobreix la pantalla (té un
            fallback CSS amb delay que acaba SEMPRE en opacity 1, així el
            títol és visible encara que el senyal no arribi mai). */}
        <div className={`w-full ${entered ? "hero-enter" : "hero-enter-wait"}`}>
          <HeroTitle />
          {/* Down Arrow */}
          <div className="mt-8">
            <ArrowDown
              size={48}
              weight="light"
              className="text-text-main animate-bounce"
            />
          </div>
        </div>
      </motion.div>

      {/* Els controls d'idioma/tema que vivien aquí ara són globals:
          veure components/common/SiteControls.tsx (muntat a SiteShell). */}
    </section>
  );
}
